import { actingAsFields } from '../lib/acting-as.js'

// Per design/stories/tower/005-accounts-roles-and-permissions.md and ADR
// 0017 (account/identity/role model). `identifiedBy: 'accountId'` --
// `accountId` is generated by the caller (node-flakes, see
// `src/lib/ids.ts`) at identity-resolution time; no `POST /accounts` route
// exists (Story 005) since accounts are only ever created via login
// resolution (`POST /identities/resolve`) or, later, invite acceptance
// that resolves through the same path.
//
// `grantedRoles`/`trialRoles` are opaque `{ name, scope }` pairs -- tower
// never interprets what a role name means (ADR 0069); it only stores,
// filters by scope, and reports them. Role *grant/revoke* command handlers
// are deliberately idempotent, defensive, set-membership operations (ADR
// 0038's ordering-defense requirement for the entitlement consumer, which
// is this actor's primary external writer besides invite redemption) --
// the command handlers themselves are thin pass-throughs; the *event*
// handlers do the idempotent merge, so replaying the same event twice
// (redelivery) or out of order is always safe.
export interface RoleGrant {
  name: string
  scope: 'tenant' | { application: string }
}

// Matches `routes/provisioning.ts`'s own `FULL_TENANT_PERMISSIONS` shape
// exactly (`{grant, scope, maxOutstanding}`) -- previously only that one
// call site's own inline object literal, never a shared type, since
// `AccountState.permissions` was `unknown[]` and nothing else read it
// structurally. Story 007's invite-code `maxOutstanding` enforcement
// (`routes/invite-codes.ts`) is the first caller that needs to, hence the
// real type now.
export interface PermissionGrant {
  grant: string
  scope: 'tenant' | { application: string }
  maxOutstanding: number | null
}

export interface UsageRecord {
  application: string
  meter: string
  periodUsage: number
  periodLimit: number | null
}

export interface ApiKeyRateLimit {
  requestsPerMinute: number
  burst?: number
}

export interface AccountState {
  accountId: string
  tenant: string
  contactId: string
  status: 'active' | 'suspended' | 'deleted'
  emailVerified: boolean
  grantedRoles: RoleGrant[]
  trialRoles: RoleGrant[]
  trialExpiresAt: string | null
  permissions: PermissionGrant[]
  usage: UsageRecord[]
  // design/decisions/0101-api-keys.md: sourced from keep's plan-mapping
  // entitlement pipeline (`lib/entitlement-consumer.ts`'s new
  // `api-key-limit-changed`/`api-key-rate-limit-changed` cases), same as
  // `organization.apiKeyLimit` below. `apiKeyLimit` defaults to `0`
  // (fail-closed), not `null` -- an account that never received a plan
  // grant can't reach `routes/api-keys.ts`'s create path anyway (it also
  // needs `api-keys:manage` in `grantedRoles`), but this keeps the limit
  // check itself fail-safe on its own, matching ADR 0100's own
  // `organization.seatLimit` null-means-one-seat divergence reasoning.
  apiKeyLimit: number | null
  apiKeyRateLimit: ApiKeyRateLimit | null
  createdAt: string
}

interface CreateCommand {
  accountId: string
  tenant: string
  contactId: string
}

interface GrantRoleCommand {
  role: RoleGrant
  actingAs?: string
}

interface RevokeRoleCommand {
  role: RoleGrant
  actingAs?: string
}

interface GrantTrialRoleCommand {
  role: RoleGrant
  trialExpiresAt: string
}

interface GrantPermissionCommand {
  permission: PermissionGrant
  actingAs?: string
}

interface RevokePermissionCommand {
  permission: { grant: string, scope: 'tenant' | { application: string } }
  actingAs?: string
}

interface UpdateUsageCommand {
  application: string
  meter: string
  periodUsage: number
  periodLimit: number | null
}

interface ChangeEmailCommand {
  contactId: string
  actingAs?: string
}

interface SetApiKeyLimitCommand {
  apiKeyLimit: number | null
}

interface SetApiKeyRateLimitCommand {
  apiKeyRateLimit: ApiKeyRateLimit | null
}

interface StatusChangeCommand {
  actingAs?: string
}

function scopeKey(scope: 'tenant' | { application: string }): string {
  return typeof scope === 'string' ? scope : `application:${scope.application}`
}

function sameRole(a: RoleGrant, b: RoleGrant): boolean {
  return a.name === b.name && scopeKey(a.scope) === scopeKey(b.scope)
}

// Story 005: "scope disambiguated... if the same grant exists at more than
// one scope" -- i.e. `(grant, scope)` together are the real identity, not
// `grant` alone. Matches `sameRole`'s own composite-scope equality
// reasoning exactly.
function samePermission(a: { grant: string, scope: 'tenant' | { application: string } }, b: { grant: string, scope: 'tenant' | { application: string } }): boolean {
  return a.grant === b.grant && scopeKey(a.scope) === scopeKey(b.scope)
}

function create(_account: AccountState, command: CreateCommand) {
  return {
    type: 'account.created',
    accountId: command.accountId,
    tenant: command.tenant,
    contactId: command.contactId,
  }
}

function grantRole(_account: AccountState, command: GrantRoleCommand) {
  return { type: 'account.role-granted', role: command.role, ...actingAsFields(command) }
}

function revokeRole(_account: AccountState, command: RevokeRoleCommand) {
  return { type: 'account.role-revoked', role: command.role, ...actingAsFields(command) }
}

function grantTrialRole(_account: AccountState, command: GrantTrialRoleCommand) {
  return { type: 'account.trial-role-granted', role: command.role, trialExpiresAt: command.trialExpiresAt }
}

// ADR 0021/0067's elevated-bootstrap case (an operator-issued or
// first-admin invite carrying `permissions`, Story 007) -- previously
// never actually applied to the account on acceptance (`invite.permissions`
// was carried on the invite record but `identities.ts`'s own redemption
// helper only ever called `account.grant-role`, never anything for
// `permissions` -- a real gap in Story 007's own "append permissions if
// present" requirement, closed here). Idempotent by `grant` string, same
// first-write-wins convention `grant-role`'s own idempotent merge uses --
// see `permissionGranted` below.
function grantPermission(_account: AccountState, command: GrantPermissionCommand) {
  return { type: 'account.permission-granted', permission: command.permission, ...actingAsFields(command) }
}

function revokePermission(_account: AccountState, command: RevokePermissionCommand) {
  return { type: 'account.permission-revoked', permission: command.permission, ...actingAsFields(command) }
}

// ADR 0076: repoints `account.contactId` to a new (or reused) contact
// record -- `contact.email` itself is immutable by design (ADR 0023), an
// email "change" is always a repoint, never an in-place edit. The route
// handler (routes/accounts.ts) is responsible for actually resolving
// `command.contactId` via `contactStore.upsert` *before* this command
// runs -- this actor only ever records the repoint, never computes the
// hash itself (no signet pepper access at this layer).
function changeEmail(_account: AccountState, command: ChangeEmailCommand) {
  return { type: 'account.contact-changed', contactId: command.contactId, ...actingAsFields(command) }
}

function setApiKeyLimit(_account: AccountState, command: SetApiKeyLimitCommand) {
  return { type: 'account.api-key-limit-set', apiKeyLimit: command.apiKeyLimit }
}

function setApiKeyRateLimit(_account: AccountState, command: SetApiKeyRateLimitCommand) {
  return { type: 'account.api-key-rate-limit-set', apiKeyRateLimit: command.apiKeyRateLimit }
}

function updateUsage(_account: AccountState, command: UpdateUsageCommand) {
  return {
    type: 'account.usage-updated',
    application: command.application,
    meter: command.meter,
    periodUsage: command.periodUsage,
    periodLimit: command.periodLimit,
  }
}

function isActive(account: AccountState) {
  return account.status === 'active'
}

function suspend(_account: AccountState, command: StatusChangeCommand) {
  return { type: 'account.suspended', ...actingAsFields(command) }
}

function rejectSuspend() {
  return Promise.reject(new Error('account must be active to be suspended'))
}

// Story 005: "status: 'active'|'suspended'|'deleted' covers suspend/
// reactivate/business-offboarding in one route" -- unlike `tenant`'s own
// PATCH (deliberately restricted to active -> suspended only, ADR 0062),
// `account` status is fully bidirectional through this single route: an
// admin can reactivate a suspended (or previously business-deleted, i.e.
// un-delete) account, same as they can suspend or delete an active one.
// `status: 'deleted'` is a business status only (offboarding) -- entirely
// distinct from GDPR erasure, which acts on `contact`, never this actor.
function isNotActive(account: AccountState) {
  return account.status !== 'active'
}

function activate(_account: AccountState, command: StatusChangeCommand) {
  return { type: 'account.activated', ...actingAsFields(command) }
}

function rejectActivate() {
  return Promise.reject(new Error('account is already active'))
}

function isNotDeleted(account: AccountState) {
  return account.status !== 'deleted'
}

function del(_account: AccountState, command: StatusChangeCommand) {
  return { type: 'account.deleted', ...actingAsFields(command) }
}

function rejectDelete() {
  return Promise.reject(new Error('account is already deleted'))
}

function created(account: AccountState, event: CreateCommand) {
  account.accountId = event.accountId
  account.tenant = event.tenant
  account.contactId = event.contactId
  account.status = 'active'
  account.emailVerified = false
  account.grantedRoles = []
  account.trialRoles = []
  account.trialExpiresAt = null
  account.permissions = []
  account.usage = []
  account.apiKeyLimit = 0
  account.apiKeyRateLimit = null
  account.createdAt = new Date(0).toISOString() // replaced by consequent's own event timestamp on read
}

// Idempotent: a redelivered/duplicate `role-granted` event for a role
// already present is a silent no-op, never a duplicate array entry.
function roleGranted(account: AccountState, event: { role: RoleGrant }) {
  if (account.grantedRoles.some((r) => sameRole(r, event.role))) return
  account.grantedRoles = [...account.grantedRoles, event.role]
}

// Idempotent + tolerant of reordering: removes the role from *both*
// grantedRoles and trialRoles (a revoke doesn't need to know which list a
// prior grant landed the role in), and is a no-op if the role is already
// absent (e.g. a redelivered revoke arriving after another revoke already
// processed it).
function roleRevoked(account: AccountState, event: { role: RoleGrant }) {
  account.grantedRoles = account.grantedRoles.filter((r) => !sameRole(r, event.role))
  account.trialRoles = account.trialRoles.filter((r) => !sameRole(r, event.role))
}

function trialRoleGranted(account: AccountState, event: { role: RoleGrant, trialExpiresAt: string }) {
  if (!account.trialRoles.some((r) => sameRole(r, event.role))) {
    account.trialRoles = [...account.trialRoles, event.role]
  }
  // Defensive against out-of-order redelivery: a later (further-future)
  // expiry never regresses to an earlier one that arrives after it.
  if (!account.trialExpiresAt || new Date(event.trialExpiresAt) > new Date(account.trialExpiresAt)) {
    account.trialExpiresAt = event.trialExpiresAt
  }
}

// First-write-wins on a duplicate `(grant, scope)` pair -- a redelivered/
// repeated grant is a silent no-op, never a duplicate array entry, matching
// `roleGranted`'s own idempotent-merge convention. Keyed on `(grant,
// scope)` together, not `grant` alone -- Story 005: the same grant string
// can exist at more than one scope simultaneously (see `samePermission`).
function permissionGranted(account: AccountState, event: { permission: PermissionGrant }) {
  if (account.permissions.some((p) => samePermission(p, event.permission))) return
  account.permissions = [...account.permissions, event.permission]
}

// Idempotent -- a no-op if the matching `(grant, scope)` is already absent
// (e.g. a redelivered revoke arriving after another already processed it).
function permissionRevoked(account: AccountState, event: { permission: { grant: string, scope: 'tenant' | { application: string } } }) {
  account.permissions = account.permissions.filter((p) => !samePermission(p, event.permission))
}

function usageUpdated(account: AccountState, event: UpdateUsageCommand) {
  const idx = account.usage.findIndex((u) => u.application === event.application && u.meter === event.meter)
  const record = {
    application: event.application,
    meter: event.meter,
    periodUsage: event.periodUsage,
    periodLimit: event.periodLimit,
  }
  if (idx === -1) {
    account.usage = [...account.usage, record]
  } else {
    account.usage = account.usage.map((u, i) => (i === idx ? record : u))
  }
}

function suspended(account: AccountState) {
  account.status = 'suspended'
}

function activated(account: AccountState) {
  account.status = 'active'
}

function deleted(account: AccountState) {
  account.status = 'deleted'
}

// Naturally idempotent -- redelivering the same `contact-changed` event
// (or the route naturally resolving to the same reused `contactId` on a
// retried request) just re-sets the same value, not a duplicate-effect
// bug the way an array-append event handler would need to guard against.
function contactChanged(account: AccountState, event: { contactId: string }) {
  account.contactId = event.contactId
}

function apiKeyLimitSet(account: AccountState, event: { apiKeyLimit: number | null }) {
  account.apiKeyLimit = event.apiKeyLimit
}

function apiKeyRateLimitSet(account: AccountState, event: { apiKeyRateLimit: ApiKeyRateLimit | null }) {
  account.apiKeyRateLimit = event.apiKeyRateLimit
}

export default function accountActor() {
  return {
    actor: {
      namespace: 'tower',
      type: 'account',
      identifiedBy: 'accountId',
      searchableBy: ['tenant', 'contactId', 'status'],
    },
    state: {
      accountId: '',
      tenant: '',
      contactId: '',
      status: 'active',
      emailVerified: false,
      grantedRoles: [],
      trialRoles: [],
      trialExpiresAt: null,
      permissions: [],
      usage: [],
      apiKeyLimit: 0,
      apiKeyRateLimit: null,
      createdAt: '',
    },
    commands: {
      create,
      'grant-role': grantRole,
      'revoke-role': revokeRole,
      'grant-trial-role': grantTrialRole,
      'grant-permission': grantPermission,
      'revoke-permission': revokePermission,
      'update-usage': updateUsage,
      'change-email': changeEmail,
      'set-api-key-limit': setApiKeyLimit,
      'set-api-key-rate-limit': setApiKeyRateLimit,
      suspend: [
        { when: isActive, then: suspend },
        rejectSuspend,
      ],
      activate: [
        { when: isNotActive, then: activate },
        rejectActivate,
      ],
      delete: [
        { when: isNotDeleted, then: del },
        rejectDelete,
      ],
    },
    events: {
      created,
      'role-granted': roleGranted,
      'role-revoked': roleRevoked,
      'trial-role-granted': trialRoleGranted,
      'permission-granted': permissionGranted,
      'permission-revoked': permissionRevoked,
      'usage-updated': usageUpdated,
      'contact-changed': contactChanged,
      'api-key-limit-set': apiKeyLimitSet,
      'api-key-rate-limit-set': apiKeyRateLimitSet,
      suspended,
      activated,
      deleted,
    },
  }
}
